function OverManegeLoungeStrokeDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local dataProviderIns = DataProvider:GetInstance()
        while not dataProviderIns:GetIsLoadSceneComplete() or not dataProviderIns:GetIsRequestHomeComplete() do
            CoYield()
        end

        self:InitData_()
        Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeFocusCat, self._cardIndex)
        self:InitAction_()
        self:FreshUI(true)
        self:FreshHandAni(false)
    end))
    return coWait
end

function OverManegeLoungeStrokeDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeShowAllCat, true)
    end))
