end

function OverManegeLoungeStrokeDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        -- if not isNull(self._catController) then
        --     self._catController:EnterSleep()
        -- end
        
        if self.__eventRequestSuccess then
            Events.RemoveListener(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, self.__eventRequestSuccess)
        end
        if self.__eventHitCat then
            Events.RemoveListener(MaidCoffeeConstants.EventNames.LoungeHitCat, self.__eventHitCat)
        end

        if self.co then
            CoStop(self.co)
            self.co = nil
        end
        if not isNull(self._tween) then
            self._tween:Kill()
            self._tween = nil
        end
        
        self.controller = nil --删除lua层引⽤用到的c#对象
        self:Delete()
        self = nil
    end))
    return coWait
end

--region init

function OverManegeLoungeStrokeDialog:InitData_()
    local parameters      = self.controller.Argument.parameters
    local playerCardId    = parameters.playerCardId
    local loungeIndex     = parameters.loungeIndex
    local cardIndex       = parameters.cardIndex
    local dataProviderIns = DataProvider:GetInstance()

    local cardInfo        = dataProviderIns:GetCardInfoByPlayerCardId(playerCardId)
    local durationOfStroking = dataProviderIns:GetDurationOfStroking()

    ---@type OverseaManageLoungeControllerNode
    local controller = dataProviderIns:GetController()
    ---@type CatTouchController
    local catController = controller:GetCatController(cardIndex)
    
    self._catController  = catController
    self._cardIndex       = cardIndex
    self._loungeIndex     = loungeIndex
    self._playerCardId    = playerCardId
    self._cardInfo        = cardInfo
    self._dataProviderIns = dataProviderIns
    self._durationOfStroking = durationOfStroking
end

function OverManegeLoungeStrokeDialog:InitAction_()
    local ClickArea         = self.ClickArea
    ClickArea.onLongPress   = Bind(self, self.OnLongPress)
    ClickArea.onPointerDown = Bind(self, self.OnPointerDown)
    ClickArea.onPointerUp   = Bind(self, self.OnPointerUp)
    ClickArea.onPointerExit   = Bind(self, self.OnPointerUp)
    
    self.__eventRequestSuccess = Events.AddListener(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, Bind(self, self.OnEventRequestSuccess))
    self.__eventHitCat         = Events.AddListener(MaidCoffeeConstants.EventNames.LoungeHitCat, Bind(self, self.OnEventHitCat))
    
end

--region init


--region logic

function OverManegeLoungeStrokeDialog:FreshUI(isInit)
    local strokingTimes = self._dataProviderIns:GetStrokingTimes()
    local touchTimes    = self._cardInfo.touchTimes
    local leftTimes     = strokingTimes - touchTimes
    self._leftTimes     = leftTimes
    
    self:FreshCardDetailStockNode()
    self:FreshStrokeShowStatus(leftTimes)
    self:FreshFeedNodes(isInit)
    
end


function OverManegeLoungeStrokeDialog:FreshStrokeShowStatus(leftTimes)
    local isHide = leftTimes <= 0
    GameUtils.UpdateUIShowState(self.Stroke.gameObject, not isHide)
    if isHide then
        return
    end
    self:FreshTextTips()
    self:FreshTextNumberProgress(MinFillAmount)
end

function OverManegeLoungeStrokeDialog:FreshCardDetailStockNode()
    ---@type OverManegeLoungeCardDetailsStrokeNode
    local env = CfUtils.GetLuaScr(self.LoungeCardDetailsStrokeNode, MaidCoffeeConstants.EnvPath.OverManegeLoungeCardDetailsStrokeNode)
    if not isNull(env) then
        env:FreshUI(self._cardInfo)
    end
    
end

function OverManegeLoungeStrokeDialog:FreshTextNumberProgress(fillAmount)
    if self._leftTimes <= 0 then
        return
    end
    self.ImgFill.fillAmount = fillAmount
    local realAmount = (fillAmount - MinFillAmount) / (MaxFillAmount - MinFillAmount)
    self.TextNumberProgress.text = string.format("%s%%", checkInt(realAmount * 100))
    self.ImgMark:SetLocalRotationZ(self:GetImgMaskRotZ(realAmount))
end

function OverManegeLoungeStrokeDialog:FreshHandAni(isTouch)
    if self._leftTimes <= 0 then
        return
    end
    self.Hand:Play(isTouch and Hand_Touch or Hand_Remind)
end

function OverManegeLoungeStrokeDialog:FreshTextTips()
    local strokingTimes = self._dataProviderIns:GetStrokingTimes()
    local leftTimes     = self._leftTimes
    local formatStr     = leftTimes > 0 and "%s/%s" or "<color=#D238A8>%s</color>/%s"
    self.TextNumberTips.text = string.format(formatStr, leftTimes, strokingTimes)
    
end

function OverManegeLoungeStrokeDialog:FreshFeedNodes(isInit)
    ---@type OverManegeLoungeFeedNodes
    local env = CfUtils.GetLuaScr(self.LoungeFeedNodes, MaidCoffeeConstants.EnvPath.OverManegeLoungeFeedNodes)
    if not isNull(env) then
        env:InitDragResponseRegion(self._catFeedingMarkers)
        env:FreshUI(true, isInit, self._loungeIndex, self._playerCardId, true)
    end
end

---FreshFeedEffectShowState
---刷新喂食效果 显示状态
function OverManegeLoungeStrokeDialog:FreshFeedEffectShowState(isShow)
    if not isShow then
        return 
    end
    if KTool.IsActive(self.UIFX_Finish) then
        local particleSystems = self._particleSystems
        for i = 0, particleSystems.Length - 1 do
            ---@type UnityEngine.ParticleSystem
            local ps = particleSystems[i]
            ps:Play(true)
        end
    else
        KTool.SetActive(self.UIFX_Finish.gameObject, true)
    end
end

--region logic


--region get/set

function OverManegeLoungeStrokeDialog:GetImgMaskRotZ(fillAmount)
    --return 308 + 102  * fillAmount
    return -52 + 102 * fillAmount
end

--region get/set


--region handler


function OverManegeLoungeStrokeDialog:OnPointerDown()
    if self.co then
        return
    end
    
    self._isPlaySe = false
    local catController = self._catController
    if isNull(catController) then return end
    catController:RandomAction()
    
    self:FreshHandAni(true)
    local durationOfStroking = self._durationOfStroking
    local tween = DOTween.To(function()
        return MinFillAmount
    end, function(fillAmount)
        self:FreshTextNumberProgress(fillAmount)
    end, MaxFillAmount, durationOfStroking)
    :OnComplete(function()
        if self._leftTimes > 0 then
            self:FreshFeedEffectShowState(true)
            self._tween = nil
            self._dataProviderIns:RequestLoungeTouch(self._cardInfo.cardDojo.id)
        end
        self._isComplete = true
    end)
    self._tween = tween
    
end

function OverManegeLoungeStrokeDialog:OnLongPress()
    local catController = self._catController
    if isNull(catController) then return end

    catController:EnterDeepInteraction()
    if not self._isPlaySe then
        self._isPlaySe = true
        CriWareUtils.PlaySe(UISheets.SFX_Function_Canteen.path, UISheets.SFX_Function_Canteen.ui_restaurant_purr)
    end
end

function OverManegeLoungeStrokeDialog:OnPointerUp()
    if self.co then
        return
    end
    self._co = CoStart(function()
        if not isNull(self._tween) then
            self:FreshHandAni(false)
            self._tween:Kill()
            self._tween = nil
            CoYield()
            self:FreshTextNumberProgress(MinFillAmount)
        end
        
        local catController = self._catController
        if not isNull(catController) then
            catController:QuitDeepInteraction()
            CriWareUtils.Stop(UISheets.SFX_Function_Canteen.path, UISheets.SFX_Function_Canteen.ui_restaurant_purr)
            CoYield()
            catController:EnterStanding()
            
            
        end
        self._co = nil
    end)
    
end

function OverManegeLoungeStrokeDialog:OnEventRequestSuccess(interface, playerCardId)
    if interface == Interfaces.MaidCoffeeLoungeFeed or interface == Interfaces.MaidCoffeeLoungeFeedAll then
        self:FreshFeedEffectShowState(true)
        self:FreshCardDetailStockNode()
        self:FreshFeedNodes()
    elseif interface == Interfaces.MaidCoffeeLoungeTouch then
        local strokingTimes = self._dataProviderIns:GetStrokingTimes()
        local touchTimes    = self._cardInfo.touchTimes
        local leftTimes     = strokingTimes - touchTimes
        self._leftTimes     = leftTimes
        self:FreshCardDetailStockNode()
        self:FreshStrokeShowStatus(leftTimes)
        self:FreshTextTips()
    end
end

function OverManegeLoungeStrokeDialog:OnEventHitCat(_, snakeId)
    local playerCardId = self._playerCardId
    ---@type OverManegeLoungeDataProvider
    local dataProviderIns = self._dataProviderIns
    local info = dataProviderIns:GetCardInfoByPlayerCardId(playerCardId)
    if info.cafeEnergy >= info.maxEnergy then
        GameUtils.Toast(localize("当前员工心情值已满"))
        return
    end
    dataProviderIns:RequestLoungeFeed(playerCardId, snakeId, true)
end

--region handler


return OverManegeLoungeStrokeDialog
 